-- Isolated provider supplement only; never a production migration. SOURCE ONLY / UNRUN.
BEGIN;
SET LOCAL search_path=public,extensions,pg_catalog;
SET LOCAL statement_timeout='20s';
-- Exact observed extension required by the current real trigram indexes.
-- Available PG17 module is required; this does not install OS packages.
CREATE EXTENSION pg_trgm WITH SCHEMA public VERSION '1.6';
DO $$ BEGIN IF current_user <> 'fixture_bootstrap' OR current_database() !~ '^qual_owner_notify_[0-9a-f]{32}$' THEN RAISE EXCEPTION 'private notification provider required'; END IF; IF to_regclass('public.operational_alert_events') IS NOT NULL THEN RAISE EXCEPTION 'inbox unexpectedly present'; END IF; IF EXISTS (SELECT 1 FROM pg_depend WHERE refobjid='public.operational_alert_events_id_seq'::regclass) THEN RAISE EXCEPTION 'retained orphan sequence acquired a consumer'; END IF; END $$;
DROP SEQUENCE public.operational_alert_events_id_seq;
CREATE TABLE public.operational_alert_events (
"id" bigint GENERATED ALWAYS AS IDENTITY (SEQUENCE NAME public.operational_alert_events_id_seq START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
"source" text NOT NULL,
"event_key" text NOT NULL,
"alertname" text NOT NULL,
"status" text NOT NULL,
"severity" text NOT NULL,
"payload" jsonb NOT NULL,
"received_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
"last_received_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
"delivery_count" bigint DEFAULT 1 NOT NULL,
"investigation_status" text DEFAULT 'new'::text NOT NULL,
"investigation" jsonb DEFAULT '{}'::jsonb NOT NULL
);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_alertname_check" CHECK (length(alertname) >= 1 AND length(alertname) <= 240);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_event_key_check" CHECK (length(event_key) >= 1 AND length(event_key) <= 512);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_investigation_status_check" CHECK (investigation_status = ANY (ARRAY['new'::text, 'investigating'::text, 'blocked'::text, 'verified_fixed'::text, 'historical'::text, 'test'::text]));
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_payload_check" CHECK (jsonb_typeof(payload) = 'object'::text AND octet_length(payload::text) <= 262144);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_pkey" PRIMARY KEY (id);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_severity_check" CHECK (length(severity) >= 1 AND length(severity) <= 40);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_source_check" CHECK (length(source) >= 1 AND length(source) <= 120);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_source_event_key_key" UNIQUE (source, event_key);
ALTER TABLE public.operational_alert_events ADD CONSTRAINT "operational_alert_events_status_check" CHECK (status = ANY (ARRAY['firing'::text, 'resolved'::text, 'info'::text]));
ALTER TABLE public.operational_alert_events OWNER TO postgres;
ALTER TABLE public.operational_alert_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.operational_alert_events FROM PUBLIC,anon,authenticated,service_role;
GRANT ALL ON public.operational_alert_events TO postgres,service_role;
GRANT ALL ON SEQUENCE public.operational_alert_events_id_seq TO postgres,anon,authenticated,service_role;
ALTER TABLE public.push_outbox ADD COLUMN next_attempt_at timestamptz;
ALTER TABLE public.push_outbox ADD CONSTRAINT "accounting_push_deferral_requires_typed_receipt" CHECK (next_attempt_at IS NULL OR accounting_notification_id IS NOT NULL AND isfinite(next_attempt_at));
CREATE OR REPLACE FUNCTION public.fn_record_operational_alert(p_source text, p_event_key text, p_alertname text, p_status text, p_severity text, p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_id bigint;
BEGIN
  INSERT INTO public.operational_alert_events(source,event_key,alertname,status,severity,payload)
  VALUES(p_source,p_event_key,p_alertname,p_status,p_severity,p_payload)
  ON CONFLICT (source,event_key) DO UPDATE
  SET last_received_at=clock_timestamp(), delivery_count=operational_alert_events.delivery_count+1
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;
