-- Isolated provider restoration only. Captured 2026-09-16T11:09:58Z from
-- kuklfnapbkmacvwxktbh; no production migration or sequence-value change.
-- Append inside provider-supplement.sql's existing bootstrap transaction.
DO $financial_sequence_preimage$
DECLARE item record;
BEGIN
  IF current_user<>'fixture_bootstrap'
     OR current_database() !~ '^qual_owner_notify_[0-9a-f]{32}$'
     OR inet_server_addr() IS NOT NULL
     OR current_setting('session_replication_role')<>'origin'
     OR (SELECT rolsuper FROM pg_roles WHERE rolname='postgres')
  THEN RAISE EXCEPTION 'private non-superuser financial provider required'; END IF;
  FOR item IN SELECT * FROM (VALUES
    ('chip_ledger_chain_seq','fixture_bootstrap'),
    ('accounting_agreement_history_id_seq','postgres'),
    ('game_management_events_sequence_seq','postgres')) q(name,owner_name)
  LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname=item.name AND c.relkind='S'
        AND pg_get_userbyid(c.relowner)=item.owner_name AND c.relacl IS NULL)
    THEN RAISE EXCEPTION 'unexpected restored financial sequence preimage: %',item.name; END IF;
  END LOOP;
END $financial_sequence_preimage$;

-- The standalone sequence has no table-owned dependency; restoring the table
-- owner did not restore this owner. Both identity sequence owners already follow
-- their captured postgres-owned tables and are asserted above, not changed.
ALTER SEQUENCE public.chip_ledger_chain_seq OWNER TO postgres;
SET LOCAL ROLE postgres;
GRANT SELECT, UPDATE, USAGE ON SEQUENCE public.chip_ledger_chain_seq,
  public.accounting_agreement_history_id_seq,
  public.game_management_events_sequence_seq
  TO postgres, anon, authenticated, service_role;
RESET ROLE;

DO $financial_sequence_postimage$
DECLARE item record; seq_oid oid;
BEGIN
  FOR item IN SELECT name FROM (VALUES('chip_ledger_chain_seq'),
    ('accounting_agreement_history_id_seq'),('game_management_events_sequence_seq')) q(name)
  LOOP
    SELECT c.oid INTO STRICT seq_oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname=item.name AND c.relkind='S'
        AND pg_get_userbyid(c.relowner)='postgres';
    IF (SELECT count(*) FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
        WHERE c.oid=seq_oid)<>12
       OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
        WHERE c.oid=seq_oid AND (pg_get_userbyid(a.grantor)<>'postgres'
          OR a.grantee NOT IN(SELECT oid FROM pg_roles
            WHERE rolname IN('postgres','anon','authenticated','service_role'))
          OR a.privilege_type NOT IN('SELECT','UPDATE','USAGE') OR a.is_grantable))
    THEN RAISE EXCEPTION 'captured financial sequence authority differs: %',item.name; END IF;
  END LOOP;
END $financial_sequence_postimage$;
COMMIT;
